import{_ as d,C as s,o as r,c,j as n,a as e,E as o,a2 as h}from"./chunks/framework.DBmpDOAE.js";const k=JSON.parse('{"title":"4. Roadmap & open questions","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/roadmap.md","filePath":"gdd/roadmap.md"}'),i={name:"gdd/roadmap.md"},l={id:"_4-1-what-exists-today",tabindex:"-1"},g={id:"_4-2-roadmap",tabindex:"-1"};function p(u,t,m,b,v,y){const a=s("Badge");return r(),c("div",null,[t[6]||(t[6]=n("h1",{id:"_4-roadmap-open-questions",tabindex:"-1"},[e("4. Roadmap & open questions "),n("a",{class:"header-anchor",href:"#_4-roadmap-open-questions","aria-label":'Permalink to "4. Roadmap & open questions"'},"​")],-1)),n("h2",l,[t[0]||(t[0]=e("4.1 What exists today ",-1)),o(a,{type:"tip",text:"Live"}),t[1]||(t[1]=e()),t[2]||(t[2]=n("a",{class:"header-anchor",href:"#_4-1-what-exists-today","aria-label":'Permalink to "4.1 What exists today <Badge type="tip" text="Live" />"'},"​",-1))]),t[7]||(t[7]=h('<ul><li>Project scaffold: Phaser 4 game, docs site and versioned web releases</li><li>Bản chơi đầu: tap → hạt chạy theo dây, va chạm mất tim, cặp vỡ (effect theo kích thước), dây Completed, thắng/thua, Hint (zoom 1.5x), pinch zoom tới 3x, hướng dẫn 3 màn đầu, nhãn Hard, 10 level mở đầu</li><li><a href="./../guide/editor">Level editor</a> tại <code>/editor/</code>, generator v2 (từ ảnh hoặc SVG, chọn 1 trong 3 phương án)</li><li>Hệ thống 100 level (bộ 5: relax / thường / khó), điểm độ khó, 100 hình SVG (<a href="./../guide/level-system">Level system</a>)</li><li>v0.3.0: bộ 30 level đang chơi (2 level hướng dẫn + chapter 5 từ tranh line art), booster Hint và Cut ở panel dưới, cảnh kết thúc slow motion, bảng màu Voxel 28 màu với cách phối theo kiểu phối màu, theme sáng/tối, editor chia chapter và generator chế độ Strokes (bóng bự, một cỡ bóng)</li><li>v0.4.0: Play on (hồi tim chơi tiếp) và pop-up &quot;Are you sure?&quot; khi QUIT, bỏ slow motion cuối level, game build đúng Play order của Organiser (<code>levels/game.json</code>), Organiser có ảnh level và chọn tutorial từng level, editor có Dot size cho cả level và ô big dot từng bóng</li><li>v0.5.0: hai bản game phụ Jelly (bóng như thạch) và Magic (level là dấu niêm phong trên cánh cửa, cửa mở ra căn phòng phía sau); giọt nước khi va chạm; hitbox 78%; màu theo nhóm tông (dây gần nhau không bao giờ cùng tông hay nhìn giống nhau, ở cả 2 theme); 30 level gen lại ở chapter 6 với bóng bự từ vòng tròn vẽ bằng nét</li><li>v0.6.0: bản game phụ Fluffy (cục bông lông có mặt, nền pattern cuộn chéo, lông bay, trail lấp lánh, tim cùng màu cặp; đánh sáng chỉnh trực tiếp bằng cheat); mỗi theme có danh sách màu riêng, màu khó nhìn được đổi sang màu không đụng dây gần nó</li></ul>',1)),n("h2",g,[t[3]||(t[3]=e("4.2 Roadmap ",-1)),o(a,{type:"warning",text:"Coming soon"}),t[4]||(t[4]=e()),t[5]||(t[5]=n("a",{class:"header-anchor",href:"#_4-2-roadmap","aria-label":'Permalink to "4.2 Roadmap <Badge type="warning" text="Coming soon" />"'},"​",-1))]),t[8]||(t[8]=h(`<p>Order of priority. Milestones are scope buckets, not dates.</p><p>Kế hoạch ban đầu (M1 bản chơi đầu, M2 kích thước hạt và HUD, M3 editor và hint) đã xong trong v0.1.0, xem 4.1.</p><h3 id="tiep-theo" tabindex="-1">Tiếp theo <a class="header-anchor" href="#tiep-theo" aria-label="Permalink to &quot;Tiếp theo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Chapter</th></tr></thead><tbody><tr><td>Chơi thử 30 level của bản v0.6.0 (chapter 6) bằng tay, chỉnh level chưa đẹp trong editor</td><td><a href="./../guide/level-system">Level system</a></td></tr><tr><td>Booster Hint, Cut và Play on: giới hạn số lượt, nối quảng cáo (hiện dùng không giới hạn)</td><td><a href="./rules">Rules</a></td></tr><tr><td>Chơi thử trên điện thoại thật: tốc độ hạt, pinch zoom</td><td><a href="./rules">Rules</a></td></tr><tr><td>Fluffy: mặt &quot;thức&quot; cho cặp đã va chạm và bàn tay tutorial lông xù (chờ ảnh <code>awake-hand.png</code>)</td><td><a href="./../guide/fluffy-assets">Fluffy assets</a></td></tr><tr><td>Thêm dây thừng và ổ khóa (obstacle) cho nhiều level hơn</td><td><a href="./rules#_3-12-obstacle-day-thung">Rules 3.12, 3.13</a></td></tr></tbody></table><h2 id="known-issues" tabindex="-1">4.3 Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;4.3 Known issues {#known-issues}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Impact</th><th>Planned fix</th></tr></thead></table><h2 id="open-questions" tabindex="-1">4.4 Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;4.4 Open questions {#open-questions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Options</th><th>Current lean</th></tr></thead><tbody><tr><td>Số cặp, số màu và độ khó qua các level</td><td><em>TBD</em></td><td>Để sau</td></tr><tr><td>Cách kiểm tra level giải được</td><td>Bằng tay / bằng công cụ</td><td><em>TBD</em></td></tr><tr><td>Thị trường mục tiêu, đối tượng người chơi</td><td><em>TBD</em></td><td><em>TBD</em></td></tr></tbody></table><h2 id="unity-shaders" tabindex="-1">4.5 Port sang Unity: lưu ý shader <a class="header-anchor" href="#unity-shaders" aria-label="Permalink to &quot;4.5 Port sang Unity: lưu ý shader {#unity-shaders}&quot;">​</a></h2><p>Game sắp được port sang Unity. Các ảnh cần đổi màu hiện được tô <strong>từng pixel trên CPU</strong> lúc chạy (canvas của trình duyệt); trên Unity nên làm bằng <strong>shader</strong> (nhanh hơn, chỉnh live không phải tạo lại texture). Bộ ảnh hiện tại dùng được với shader vì các ảnh cần tô màu đều là <strong>ảnh xám</strong>. Công thức dưới đây chép từ code để bản Unity ra giống bản web.</p><h3 id="anh-nao-dung-shader-nao" tabindex="-1">Ảnh nào dùng shader nào <a class="header-anchor" href="#anh-nao-dung-shader-nao" aria-label="Permalink to &quot;Ảnh nào dùng shader nào&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ảnh</th><th>Cách dùng trên Unity</th><th>Code web tương ứng</th></tr></thead><tbody><tr><td><code>src/assets/fluffy/ball.png</code> (xám, chưa có ánh sáng)</td><td>Shader <strong>tô màu + đánh sáng cầu</strong> (công thức bên dưới)</td><td><code>ballTexture</code> trong <code>src/scenes/fluffy.ts</code></td></tr><tr><td><code>src/assets/fluffy/heart.png</code> (đỏ)</td><td>Shader tô màu theo kênh sáng nhất (dùng nguyên ảnh đỏ được)</td><td><code>heartTexture</code> trong <code>src/scenes/fluffy.ts</code></td></tr><tr><td><code>src/assets/fluffy/fur.png</code> (trắng)</td><td>Không cần shader: tô bằng màu hạt của Particle System</td><td><code>furPuff</code> trong <code>src/scenes/Game.ts</code></td></tr><tr><td><code>src/assets/fluffy/face-*.png</code></td><td>Không cần shader: sprite chồng lên thân (rộng 68% đường kính thân, hạ 10% bán kính)</td><td><code>faceFrame</code> trong <code>src/scenes/fluffy.ts</code></td></tr><tr><td><code>src/assets/fluffy/pattern-*.jpg</code></td><td>Material lặp ô, Wrap Mode = Repeat, dịch UV để cuộn chéo (4 px/giây), mỗi ô phủ 1024 px board</td><td><code>bg</code> trong <code>src/scenes/Game.ts</code></td></tr><tr><td><code>src/assets/magic/orb.png</code> (xám, đã bỏ nền xanh)</td><td>Shader tô màu như thân cục lông nhưng không có đèn (công thức orb bên dưới)</td><td><code>colourOrb</code> trong <code>src/scenes/Door.ts</code></td></tr><tr><td><code>src/assets/magic/door.jpg</code></td><td>Shader: màu nền theme + 35% vân sáng tối của ảnh quanh độ sáng trung bình</td><td><code>makeDoor</code> trong <code>src/scenes/Door.ts</code></td></tr><tr><td><code>src/assets/magic/light-ray.jpg</code>, <code>light-burst.jpg</code>, <code>sparkle.jpg</code> (nền đen)</td><td>Shader <strong>cộng sáng (Additive)</strong>: nền đen tự biến mất</td><td><code>Door.ts</code></td></tr></tbody></table><h3 id="cong-thuc" tabindex="-1">Công thức <a class="header-anchor" href="#cong-thuc" aria-label="Permalink to &quot;Công thức&quot;">​</a></h3><p>Ký hiệu: <code>grey</code> là độ sáng của pixel ảnh (trung bình R, G, B, từ 0 tới 1); <code>mid</code> là độ sáng trung bình của phần đặc của ảnh (alpha &gt; 200), <strong>tính một lần cho mỗi ảnh</strong> rồi truyền vào shader dưới dạng hằng số; <code>col</code> là màu của cặp (<code>base</code> trong bảng màu).</p><p><strong>Thân cục lông (Fluffy).</strong> Pháp tuyến cầu lấy từ UV: tâm và bán kính là vùng đặc của ảnh (thân chiếm 90% khung). Ngoài vòng tròn thì kéo pháp tuyến về mép (<code>nz = 0</code>). Hướng đèn từ 5 số <code>LIGHT_*</code> trong <code>src/game/tuning.ts</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a = LIGHT_ANGLE (độ, 0 phải, 90 dưới, 180 trái, 270 trên)    h = LIGHT_HEIGHT</span></span>
<span class="line"><span>light = (cos a · √(1−h²), sin a · √(1−h²), h)</span></span>
<span class="line"><span>lit   = max(0, dot(normal, light))</span></span>
<span class="line"><span>shade = LIGHT_AMBIENT + LIGHT_DIFFUSE · lit</span></span>
<span class="line"><span>L     = clamp(mid · shade + LIGHT_SHEEN · lit⁴ + (grey − mid) · (0.6 + 0.4 · shade), 0, 1)</span></span>
<span class="line"><span>màu   = L &lt; mid ? col · (0.3 + 0.7 · L / mid)</span></span>
<span class="line"><span>               : col + (1 − col) · ((L − mid) / (1 − mid))^1.4 · 0.55</span></span></code></pre></div><p><strong>Orb (Magic):</strong> giống dòng <code>màu</code> ở trên với <code>L = grey</code>, nhưng <code>0.25 + 0.75 · L / mid</code> cho phần tối và không có hệ số <code>0.55</code> cho phần sáng (điểm sáng thành trắng hẳn).</p><p><strong>Trái tim:</strong> <code>mx</code>, <code>mn</code> là kênh lớn nhất và nhỏ nhất của pixel; phần ít màu (điểm bóng) giữ trắng:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>white = max(0, (1 − (mx − mn) / mx) − 0.25) / 0.75</span></span>
<span class="line"><span>v     = col · min(1, mx · 1.08)</span></span>
<span class="line"><span>màu   = v + (1 − v) · white · mx</span></span></code></pre></div><h3 id="choi-tiep-level-đang-do" tabindex="-1">Chơi tiếp level đang dở <a class="header-anchor" href="#choi-tiep-level-đang-do" aria-label="Permalink to &quot;Chơi tiếp level đang dở&quot;">​</a></h3><p>Lưu level đang chơi (xem Rules 3.11) bằng <code>PlayerPrefs</code> / file JSON, ghi khi trạng thái đổi và trong <code>OnApplicationPause(true)</code>, <code>OnApplicationQuit</code>; mở app thì vào thẳng level nếu có phần đã lưu khớp level đang tới.</p><h3 id="luu-y-khi-lam-shader" tabindex="-1">Lưu ý khi làm shader <a class="header-anchor" href="#luu-y-khi-lam-shader" aria-label="Permalink to &quot;Lưu ý khi làm shader&quot;">​</a></h3><ul><li><strong>Dùng ảnh trong <code>src/assets/fluffy/</code>, không dùng <code>art/fluffy/</code>.</strong> Ảnh gốc trong <code>art/</code> còn ánh sáng sẵn và lông chưa làm đậm (lệnh <code>npm run art:fluffy</code> làm việc đó); dùng nó với shader thì ánh sáng bị chồng hai lần.</li><li><strong>Không gian màu:</strong> bản web tính màu trong sRGB (gamma). Unity mặc định dùng Linear, nên cùng công thức sẽ ra màu khác (thường nhạt, phẳng hơn). Hoặc đặt project ở <strong>Gamma</strong>, hoặc trong shader đổi màu sang gamma trước khi tính rồi đổi lại.</li><li><strong>Tọa độ:</strong> web có trục y hướng xuống, Unity hướng lên. Góc đèn (<code>LIGHT_ANGLE</code>), hướng lông bay và quạt giọt nước phải đảo trục y (đèn trên trái là 230° trên web, khoảng 130° trên Unity).</li><li><strong>Màu mỗi cặp qua vertex color</strong> (màu của SpriteRenderer hoặc MaterialPropertyBlock), không tạo material riêng cho từng màu, để 30 cặp vẫn được vẽ chung một lượt (batch). Màu cụ thể vẫn do code chọn theo theme (<code>themeColours</code> trong <code>src/core/palette.ts</code>), shader chỉ nhận màu đã chọn.</li><li><strong>Đèn chỉnh live:</strong> 5 số <code>LIGHT_*</code> thành tham số của material (dùng chung cho mọi cục lông), chỉnh được trong Play mode như cheat ⚙ dev của bản web.</li><li><strong>Mép ảnh trong suốt:</strong> PNG từ <code>npm run art:fluffy</code> không nhân sẵn alpha (premultiplied). Khi import bật <em>Alpha Is Transparency</em> để mép lông không bị viền tối.</li><li><strong>Nén ảnh:</strong> pattern đang 2508 × 2508 (không phải lũy thừa của 2). Nén ASTC trên điện thoại vẫn được; nếu cần máy iOS rất cũ (PVRTC) thì thu về 2048.</li><li><strong>Dây và bóng bản Classic, Jelly</strong> đang vẽ bằng code mỗi khung hình (không có ảnh). Trên Unity cần mesh dây tự dựng (hoặc plugin như Shapes) và một sprite bóng xám tô màu bằng shader như orb, hoặc shader vẽ hình tròn.</li></ul>`,23))])}const x=d(i,[["render",p]]);export{k as __pageData,x as default};
